function notifyView({ immediate = false } = {}) {
  clearTimeout(viewTimer);
  const run = () => {
    if (destroyed || !view || !bounds) return;
    const param = formatViewParam(view, bounds);
    if (param === lastViewParam) return;
    lastViewParam = param;
    onViewChange?.(param);
  };
  if (immediate) run();
  else viewTimer = setTimeout(run, 400);
}

