    if (press > 0) await cdp.pressKey('+', { keyCode: 187 });
    outside = await cdp
      .waitFor(
        `(() => {
          const figure = document.querySelectorAll('#compare-view-body .app-compare__pane')[1];
          if (!figure || figure.dataset.coverage !== 'outside') return null;
          const note = figure.querySelector('[data-compare-coverage="1"]');
          return {
            coverage: figure.dataset.coverage,
            note: note?.textContent || '',
            noteHidden: note?.hidden === true,
            readout: figure.querySelector('[data-compare-readout]')?.textContent || '',
            hint: document.querySelector('#compare-sync-hint')?.textContent || '',
          };
        })()`,
        { label: `outside coverage after ${press + 1} zoom step(s)`, timeout: 6_000 },
