const userDataDir = await mkdtemp(path.join(os.tmpdir(), 'probe-out-'));
const chrome = spawn(
  'chromium',
  ['--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage', '--hide-scrollbars', '--window-size=1440,960', `--remote-debugging-port=${PORT}`, `--user-data-dir=${userDataDir}`, 'about:blank'],
  { stdio: ['ignore', 'ignore', 'ignore'] },
);
try {
  const deadline = Date.now() + 30000;
  let target = null;
  while (Date.now() < deadline) {
    try {
      const res = await fetch(`http://127.0.0.1:${PORT}/json/new?about:blank`, { method: 'PUT' });
      if (res.ok) { const info = await res.json(); if (info.webSocketDebuggerUrl) { target = info.webSocketDebuggerUrl; break; } }
    } catch {}
    await sleep(300);
  }
  if (!target) throw new Error('no devtools target');
  const ws = new WebSocket(target);
  await new Promise((resolve) => ws.addEventListener('open', resolve, { once: true }));
  const cdp = new CDP(ws);
  await cdp.send('Page.enable');
  await cdp.send('Runtime.enable');
  const pair = 'e-rara:3946379,e-rara:8562848';
  await cdp.send('Page.navigate', { url: `${BASE}/?cmp=${encodeURIComponent(pair)}` });
  await cdp.waitFor(`document.querySelectorAll('#result-list > *').length > 0`, { label: 'rows' });
  await sleep(500);
  await cdp.click('#compare-open');
  await cdp.waitFor(`document.querySelector('#compare-view') && !document.querySelector('#compare-view').hidden`, { label: 'view' });
  await cdp.waitFor(`(() => { const panes = [...document.querySelectorAll('#compare-view-body .app-compare__pane')]; return panes.length === 2 && panes.every((p) => p.querySelector('[data-compare-stage]')?.dataset.state === 'ready'); })()`, { label: 'panes', timeout: 60000 }).catch(() => console.log('panes not ready'));
  await cdp.eval(`document.querySelector('[data-compare-stage="0"]').focus(); true`);
  for (let press = 0; press < 6; press += 1) {
    if (press > 0) await cdp.key('+', { code: 'Equal', keyCode: 187 });
    await sleep(1200);
    const state = await cdp.eval(`(() => {
      const figure = document.querySelectorAll('#compare-view-body .app-compare__pane')[1];
      const note = figure?.querySelector('[data-compare-coverage="1"]');
      return { coverage: figure?.dataset.coverage, note: note?.textContent, noteHidden: note?.hidden, readout: figure?.querySelector('[data-compare-readout]')?.textContent, hint: document.querySelector('#compare-sync-hint')?.textContent };
    })()`);
    console.log('press', press, JSON.stringify(state));
    if (state.coverage === 'outside') break;
  }
} finally {
  chrome.kill('SIGKILL');
}
EOF
